import re

def parse_range(header, size):
    if not header or 'bytes=' not in header:
        return None

    try:
        # Extract the part after 'bytes='
        parts_str = header.split('bytes=')[-1].split(',')[0]
        # Handle multiple ranges if present in the header string
        # The RFC says "a set of ranges", so we split by comma
        raw_ranges = header.split('bytes=')[-1].split(',')

        results = []
        any_satisfiable = False

        for r in raw_ranges:
            r = r.strip()
            if not r: continue

            try:
                if '-' in r:
                    parts = r.split('-')
                    start_str = parts[0].strip()
                    end_str = parts[1].strip() if len(parts) > 1 else ""

                    # Handle suffix (e.g., -500)
                    if start_str.startswith('-'):
                        suffix_len = int(start_str[1:])
                        start = max(0, size - suffix_len)
                        end = size - 1
                    else:
                        start = int(start_str)
                        if end_str == "":
                            end = size - 1
                        else:
                            end = int(end_str)
                else:
                    # Single point range (e.g., bytes=500)
                    start = int(r)
                    end = start

                # Clamp end to size
                end = min(end, size - 1)

                # Check satisfiability
                if start < size and start <= end:
                    results.append((start, end))
                    any_satisfiable = True
                else:
                    # Range is unsatisfiable, skip it
                    pass
            except ValueError:
                return None # Malformed

        return results if any_satisfiable else None
    except Exception:
        return None
```

