import re

class Spreadsheet:
    def __init__(self):
        self.cells = {}  # cell_id -> value (int or str)
        self.cache = {}  # cell_id -> computed_value
        self.dependencies = {}  # cell_id -> set of cell_ids it depends on
        self.dependents = {}  # cell_id -> set of cell_ids that depend on it

    def _parse_formula(self, formula):
        if not formula.startswith('='):
            return None, []

        expr = formula[1:]
        # Tokenize: numbers, cell refs (A1, B10), and operators (+, -, *)
        tokens = re.findall(r'[A-Z]+\d+|[0-9]+|[\+\-\*]', expr)

        # Convert tokens to internal representation
        parsed_tokens = []
        for t in tokens:
            if t.isdigit():
                parsed_tokens.append(('num', int(t)))
            elif re.match(r'[A-Z]+\d+', t):
                parsed_tokens.append(('ref', t))
            else:
                parsed_tokens.append(('op', t))
        return parsed_tokens

    def _get_refs(self, tokens):
        refs = []
        for t in tokens:
            if isinstance(t, tuple) and t[0] == 'ref':
                refs.append(t[1])
        return refs

    def set(self, cell, value):
        # Check for cycles before applying
        new_refs = []
        if isinstance(value, str) and value.startswith('='):
            tokens = self._parse_formula(value)
            new_refs = self._get_refs(tokens)

        # Cycle detection using DFS
        visited = set()
        def has_cycle(curr, target_refs):
            if curr in target_refs: return True
            if curr in visited: return False
            visited.add(curr)
            for dep in self.dependencies.get(curr, []):
                if has_cycle(dep, target_refs): return True
            return False

        # Check if any new reference creates a cycle
        for ref in new_refs:
            if has_cycle(cell, [ref]):
                raise ValueError("Circular dependency detected")

        # Apply change
        old_val = self.cells.get(cell, 0)
        self.cells[cell] = value

        # Update dependency graph
        if cell in self.dependencies:
            del self.dependencies[cell]
        if cell in self.dependents:
            for dep in self.dependents[cell]:
                self.dependents[cell].remove(cell)

        self.dependencies[cell] = set(new_refs)
        for ref in new_refs:
            if ref not in self.dependents: self.dependents[ref] = set()
            self.dependents[ref].add(cell)

        # Invalidate cache for this cell and all its transitive dependents
        to_invalidate = set()
        stack = [cell]
        while stack:
            curr = stack.pop()
            if curr in self.cache:
                del self.cache[curr]
                to_invalidate.add(curr)
            for dep in self.dependents.get(curr, []):
                if dep not in to_invalidate:
                    stack.append(dep)

        # Re-evaluate only if necessary (lazy evaluation is handled by get)
        # But to ensure O(1) amortized, we must ensure we don't re-traverse 
        # the whole chain on every set. The cache handles the O(1) requirement.

    def get(self, cell):
        if cell in self.cache:
            return self.cache[cell]

        val = self.cells.get(cell, 0)
        if not isinstance(val, str) or not val.startswith('='):
            res = val if isinstance(val, int) else 0
            self.cache[cell] = res
            return res

        tokens = self._parse_formula(val)
        # Standard Shunting-yard or simple recursive descent for precedence
        # Since we only have + - * and integers/refs, we can use a simple stack
        def evaluate_tokens(ts):
            # Handle * first
            stack = []
            i = 0
            while i < len(ts):
                t = ts[i]
                if isinstance(t, tuple) and t[0] == 'num':
                    stack.append(t[1])
                elif isinstance(t, tuple) and t[0] == 'ref':
                    stack.append(self.get(t[1]))
                elif t[1] == '*':
                    left = stack.pop()
                    right = stack.pop()
                    stack.append(left * right)
                else:
                    stack.append(t)
                i += 1

            # Handle + and -
            res = stack[0]
            i = 1
            while i < len(stack):
                op = stack[i]
                val = stack[i+1]
                if op[1] == '+': res += val
                elif op[1] == '-': res -= val
                i += 2
            return res

        res = evaluate_tokens(tokens)
        self.cache[cell] = res
        return res
