function deepEqual(a, b) {
  if (a === b) {
    // Handle +0 vs -0 (SameValueZero treats them as equal, 
    // but if you strictly need SameValue, use Object.is. 
    // SameValueZero: +0 === -0 is true.
    return true;
  }

  if (typeof a !== typeof b) return false;

  // NaN equals NaN
  if (typeof a === 'number' && isNaN(a) && isNaN(b)) return true;

  if (a === null || b === null || typeof a !== 'object') return false;

  // Date comparison
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // RegExp comparison
  if (a instanceof RegExp && b instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }

  // Map comparison
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (let [key, val] of a) {
      if (!b.has(key) || !deepEqual(val, b.get(key))) return false;
    }
    return true;
  }

  // Set comparison
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    const bArr = Array.from(b);
    for (let aVal of a) {
      if (!bArr.some(bVal => deepEqual(aVal, bVal))) return false;
    }
    return true;
  }

  // Array and Plain Object comparison with Cycle Detection
  const visited = new WeakMap();

  function compare(x, y) {
    if (x === y) return true;
    if (typeof x !== 'object' || x === null || typeof y !== 'object' || y === null) return false;

    // Check for cycles
    if (visited.has(x) && visited.has(y)) return true;
    visited.set(x, y);

    const keysX = Object.keys(x);
    const keysY = Object.keys(y);

    if (keysX.length !== keysY.length) return false;

    for (const key of keysX) {
      if (!Object.prototype.hasOwnProperty.call(y, key)) return false;
      if (!compare(x[key], y[key])) return false;
    }

    return true;
  }

  return compare(a, b);
}

module.exports = deepEqual;
