function debounce(fn, wait, options = {}) {
  let timeoutId = null;
  let lastArgs = null;
  let lastContext = null;
  let lastResult = null;
  let lastCallTime = 0;

  const leading = !!options.leading;
  const trailing = !!options.trailing;

  function invoke() {
    const args = lastArgs;
    const context = lastContext;
    lastArgs = null;
    lastContext = null;
    lastResult = fn.apply(context, args);
    return lastResult;
  }

  function startTimer() {
    timeoutId = setTimeout(() => {
      if (trailing && lastArgs !== null) {
        invoke();
      }
      timeoutId = null;
    }, wait);
  }

  const debounced = function(...args) {
    const now = Date.now();
    const isInvokedLeading = leading && !timeoutId && (lastCallTime === 0 || now - lastCallTime > wait);

    lastArgs = args;
    lastContext = this;
    lastCallTime = now;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    if (isInvokedLeading) {
      lastResult = fn.apply(this, args);
      lastArgs = null;
      lastContext = null;
      if (trailing) {
        startTimer();
      }
    } else {
      startTimer();
    }

    return lastResult;
  };

  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    timeoutId = null;
    lastArgs = null;
    lastContext = null;
  };

  debounced.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (lastArgs !== null) {
      lastResult = invoke();
    }
    return lastResult;
  };

  return debounced;
}

