  if (iterables.length === 0) return;

  const iterators = iterables.map(it => (typeof it[Symbol.iterator] === 'function' ? it[Symbol.iterator]() : it));
  const active = new Array(iterators.length).fill(true);

  while (active.some(active => active)) {
    const row = [];
    for (let i = 0; i < iterators.length; i++) {
      if (active[i]) {
        const { value, done } = iterators[i].next();
        if (done) {
          active[i] = false;
          row.push(fill);
        } else {
          row.push(value);
        }
      } else {
        row.push(fill);
      }
    }
    yield row;
  }
}

