      if (p && p.status === 'rejected') {
        errors.push(p.reason);
      }
    }

    if (errors.length > 0) {
      throw errors[0];
    }

    return finalResults;
  } catch (err) {
    if (err.message.includes('cycle')) throw err;
    throw err;
  }
