export type RouteParams = Record<string, string>;

export function defineRoutes<
  T extends Record<string, string>,
  K extends keyof T
>(routes: T): Record<K, (params: T[K] extends any ? (T[K] extends string ? RouteParams : never) : never) => string> {
  const result = {} as any;

  for (const key in routes) {
    const path = routes[key];
    const params = Object.keys(routes) as Array<keyof T>;

    // This is a structural helper to extract param names from the string
    // and ensure the function signature matches the path.
    const paramNames = (path.match(/:(\w+)/g) || []).map(p => p.slice(1));

    // The actual logic for the return value
    result[key] = (params: any) => {
      let interpolated = path;
      paramNames.forEach(name => {
        interpolated = interpolated.replace(`:${name}`, params[name]);
      });
      return interpolated;
    };
  }

  return result;
